import json
n=30
out=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
centers=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Tile frames are 5x5 in color 4; their 3x3 interiors carry the pattern.
for i,rs in enumerate(starts):
 for j,cs in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=rs+dr,cs+dc
    if r<n and c<n: out[r][c]=4
    if i<4 and j<4 and 1<=dr<=3 and 1<=dc<=3: out[r][c]=centers[i][j]
# Join non-dominant center colors across the two-cell gaps in each row.
for i in range(4):
 for color in (3,8):
  js=[j for j,v in enumerate(centers[i]) if v==color]
  if len(js)>1:
   for j in range(min(js),max(js)):
    for r in range(starts[i]+1,starts[i]+4):
     for c in range(starts[j]+5,starts[j]+7): out[r][c]=color
# Join matching center colors vertically through gaps.
for j in range(4):
 for color in (3,8):
  is_=[i for i in range(4) if centers[i][j]==color]
  if len(is_)>1:
   for i in range(min(is_),max(is_)):
    for r in range(starts[i]+5,starts[i]+7):
     for c in range(starts[j]+1,starts[j]+4): out[r][c]=color
print(json.dumps(out,separators=(',',':')))
